#[test]
fn scaled_matches_the_css_at_every_step() {
    for &(ti, n, r, want) in CASES {
        let s = scaled(THEMES[ti].2, n, r);
        let got = [s.ui_text_scale, s.text_title, s.text_body, s.text_sender, s.text_channel, s.text_member, s.text_section, s.text_meta, s.text_reply, s.text_reply_line_height, s.text_micro, s.list_row_avatar_scale];
        for (i, (g, w)) in got.iter().zip(want.iter()).enumerate() {
            assert!((*g as f64 - w).abs() <= 1e-5 * w.abs().max(1.0), "{} @ {n}px x{r}: field {i} = {g}, CSS says {w}", THEMES[ti].0);
        }
    }
}
